using System;using System.Text;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckBungeeDemolition {
public enum BungeePhase{Countdown,Demolition,Finale,RoundResult}
public sealed class BungeeMatch:SportsEventSession {
 public AudioSource rumble,siren;public BungeeBay[] bays;public SportsEventCamera broadcast;public SportsEventCamera[] playerViews;public BungeePhase Phase{get;private set;}public float Clock{get;private set;}public int Round{get;private set;}public int Winner{get;private set;}=-1;public bool Scoring=>Live&&Phase==BungeePhase.Demolition;public readonly int[] total=new int[4];public int HumanViews{get;private set;}public readonly int[] viewOwners=new int[4];public int CompletedRounds{get;private set;}public int FinaleScoreChanges{get;private set;}
 readonly Vector2[] ai=new Vector2[4];readonly float[] nextThink=new float[4];readonly float[] retreatUntil=new float[4];readonly int[] locked=new int[4];readonly bool[] contenders=new bool[4];float phaseTime;int releasedLevel,spectator;bool overtime;readonly StringBuilder text=new StringBuilder(600);
 public override string Title=>"TRUCK BUNGEE DEMOLITION";public override int MinimumPlayers=>1;public override int MaximumPlayers=>4;public override int OptionCount=>1;public override int WeatherCount=>1;public override string OptionLabel=>"3 ROUNDS · 60 SECOND DEMOLITION";public override bool MultiViewHUD=>Phase==BungeePhase.Countdown||Phase==BungeePhase.Demolition;public override bool ReplayControls=>Phase==BungeePhase.Finale&&phaseTime>3;
 public override string Help=>"Your truck is the wrecking ball. Pump with movement controls; ACTION gives a short reel tug on cooldown. Physical impacts damage tower supports and can bring upper floors down. Each structural module scores only once; loose rubble cannot farm points. Three simultaneous 60-second rounds, most destruction points wins. Tied leaders play a 20-second extra round. The siren locks scores BEFORE the automatic demolition finale. Finale destruction awards no points. A genuine stuck truck is rehung with three seconds of lost control. Escape pauses all bays; reconnect preserves current state.";
 public override string Header=>Title+" · ROUND "+Round+(overtime?" TIEBREAK":" / 3");public override string Status=>Phase==BungeePhase.Countdown?Mathf.CeilToInt(Clock).ToString():Phase==BungeePhase.Demolition?Clock.ToString("F1")+"s · DIRECTION PUMPS · ACTION TUG":Phase==BungeePhase.Finale?"SCORING LOCKED · CONTROLLED DEMOLITION":"ROUND SCORES BANKED";
 public override string Standings{get{text.Clear();for(int i=0;i<setup.count;i++)text.Append(setup.players[i].name).Append(" · ").Append(bays[i].Score).Append(" THIS ROUND · ").Append(total[i]).Append(" BANKED\n");return text.ToString();}}
 public override string Results=>(Winner>=0?setup.players[Winner].name+" WINS":"TIE")+"\n\n"+Standings;public override string ViewText(int v){int i=HumanViews==0?spectator:viewOwners[v];var b=bays[i];return "<color=#"+ColorUtility.ToHtmlStringRGB(setup.players[i].color)+">"+setup.players[i].name+"</color> · ROUND "+Round+" · "+Status+"\n"+b.Score+" ROUND · "+total[i]+" BANKED · "+(b.Maximum>0?Mathf.RoundToInt(b.Score*100f/b.Maximum):0)+"% DESTRUCTION\n"+(b.RecoveryTime>0?"REHANGING · "+b.RecoveryTime.ToString("F1")+"s":b.Cooldown>0?"TUG "+b.Cooldown.ToString("F1")+"s":"TUG READY");}
 protected override void BeginGame(){Array.Clear(total,0,4);Array.Clear(nextThink,0,4);Round=1;CompletedRounds=FinaleScoreChanges=0;Winner=-1;overtime=false;for(int i=0;i<4;i++)contenders[i]=i<setup.count;Layout();StartRound();}
 void Layout(){HumanViews=0;for(int i=0;i<setup.count;i++)if(setup.players[i].source!=BowlingSource.AI)viewOwners[HumanViews++]=i;cameras=HumanViews==0?new[]{broadcast.view}:new Camera[HumanViews];broadcast.view.enabled=HumanViews==0;broadcast.view.rect=new Rect(0,0,1,1);for(int i=0;i<4;i++){playerViews[i].view.enabled=i<HumanViews;if(i<HumanViews){playerViews[i].view.rect=LWS.TruckCornhole.CornholeMatch.ViewRect(HumanViews,i);cameras[i]=playerViews[i].view;}}}
 void StartRound(){Array.Clear(retreatUntil,0,4);for(int i=0;i<4;i++){bays[i].gameObject.SetActive(i<setup.count);if(i<setup.count)bays[i].ResetBay();}Phase=BungeePhase.Countdown;Clock=3;phaseTime=0;releasedLevel=-1;Layout();Gate();}
 protected override void Simulate(float dt){phaseTime+=dt;if(Phase==BungeePhase.Countdown){Clock=Mathf.Max(0,Clock-dt);if(Clock<=0){Phase=BungeePhase.Demolition;Clock=overtime?20:60;phaseTime=0;for(int i=0;i<setup.count;i++)if(contenders[i])bays[i].Release();feedback.Play(2,0,true);}return;}
 if(Phase==BungeePhase.Demolition){Clock=Mathf.Max(0,Clock-dt);if(Clock<=0){for(int i=0;i<setup.count;i++){locked[i]=bays[i].Score;total[i]+=locked[i];bays[i].ReelClear();}Phase=BungeePhase.Finale;phaseTime=0;if(siren!=null){siren.volume=settings.sfx*.25f;siren.Play();}feedback.Play(2,0,true);foreach(var view in playerViews)view.view.enabled=false;broadcast.view.enabled=true;broadcast.view.rect=new Rect(0,0,1,1);cameras=new[]{broadcast.view};return;}for(int i=0;i<setup.count;i++){if(!contenders[i])continue;var b=bays[i];b.RecoveryTick(dt);if(setup.players[i].source==BowlingSource.AI){Think(i);commands[i]=ai[i];actions[i]=b.Cooldown<=0&&Vector3.Dot(b.truck.body.linearVelocity,new Vector3(ai[i].x,0,ai[i].y))>2;}b.Tick(commands[i],actions[i],dt);}return;}
 if(Phase==BungeePhase.Finale){for(int i=0;i<setup.count;i++)if(bays[i].Score!=locked[i])FinaleScoreChanges++;int level=Mathf.FloorToInt((phaseTime-1)*2);while(releasedLevel<Mathf.Min(9,level)){releasedLevel++;for(int i=0;i<setup.count;i++)bays[i].FinaleStep(releasedLevel);}if(phaseTime>9)EndRound();return;}
 if(phaseTime>2.5f){Round++;StartRound();}}
 void EndRound(){if(Phase!=BungeePhase.Finale)return;CompletedRounds++;Phase=BungeePhase.RoundResult;phaseTime=0;if(Round<3)return;int best=int.MinValue,count=0;for(int i=0;i<setup.count;i++)best=Mathf.Max(best,total[i]);for(int i=0;i<setup.count;i++){contenders[i]=total[i]==best;if(contenders[i]){Winner=i;count++;}}if(setup.count==1){int old=SportsPrefs.GetInt("TruckBungeeDemolition.PersonalBest",0);if(total[0]>old){SportsPrefs.SetInt("TruckBungeeDemolition.PersonalBest",total[0]);SportsPrefs.Save();}}if(count==1||setup.count==1){EndMatch();return;}overtime=true;Winner=-1;}
 public override void ExtraAction(string key){if(key=="replayskip"&&Phase==BungeePhase.Finale&&phaseTime>3){for(int level=0;level<10;level++)for(int i=0;i<setup.count;i++)bays[i].FinaleStep(level);EndRound();}}
 void Think(int i){if(Time.time<nextThink[i])return;float skill=(int)setup.players[i].difficulty;nextThink[i]=Time.time+Mathf.Lerp(.65f,.22f,skill*.5f);var b=bays[i];Vector3 origin=b.truck.body.position;BungeeModule best=null;float rating=float.MinValue;foreach(var m in b.modules){if(m==null||!m.gameObject.activeInHierarchy||m.core.HasCollapsed)continue;var p=m.transform.position;float reach=Mathf.Abs(p.y-origin.y);float value=m.budget*2-reach*.8f-Vector3.Distance(origin,p)*.2f+(m.level<4?5:0);if(value>rating){rating=value;best=m;}}if(best==null){ai[i]=Vector2.zero;return;}var aim=best.transform.position-origin;var velocity=b.truck.body.linearVelocity;float error=Mathf.Sin(Time.time*.71f+i*5.3f)*(2-skill*.65f);var desired=new Vector2(aim.x+error,aim.z-error).normalized;var planar=new Vector2(velocity.x,velocity.z);float gap=new Vector2(aim.x,aim.z).magnitude;if(gap<10&&planar.magnitude<7&&Time.time>retreatUntil[i]+2)retreatUntil[i]=Time.time+3.8f-skill*.25f;if(Time.time<retreatUntil[i]){var axis=Vector3.ProjectOnPlane(b.towerMount.position-b.craneAnchor.position,Vector3.up).normalized;desired=-new Vector2(axis.x,axis.z);}ai[i]=Vector2.ClampMagnitude(desired*(1+Mathf.Min(1,gap/8))-planar*.015f,1);}
 protected override void Present(float dt){if(bays==null||bays.Length==0)return;if(rumble!=null){bool active=Live&&Phase==BungeePhase.Finale&&Application.isFocused;rumble.volume=active?settings.sfx*.28f*Mathf.Clamp01((9-phaseTime)/2):0;if(active&&!rumble.isPlaying&&phaseTime*.65f<rumble.clip.length-.05f){rumble.time=phaseTime*.65f;rumble.Play();}else if(!active&&rumble.isPlaying)rumble.Stop();}if(Phase==BungeePhase.Finale){broadcast.view.farClipPlane=2000;float center=(setup.count-1)*100;float aspect=Mathf.Max(.5f,broadcast.view.aspect);float distance=Mathf.Max(90,((setup.count-1)*200+100)/(2*Mathf.Tan(30*Mathf.Deg2Rad)*aspect)+30);broadcast.Pose(new Vector3(center,24,8),new Vector3(0,70,-distance),60);return;}if(HumanViews==0){broadcast.view.farClipPlane=160;int i=Mathf.FloorToInt(Time.time/12)%Mathf.Max(1,setup.count);spectator=i;var b=bays[i];broadcast.Pose(Vector3.Lerp(b.truck.body.position,b.towerMount.position+Vector3.up*25,.35f),new Vector3(-22,14,-34),70);return;}for(int v=0;v<HumanViews;v++){var b=bays[viewOwners[v]];var focus=Vector3.Lerp(b.truck.body.position,b.towerMount.position+Vector3.up*24,.3f);playerViews[v].Pose(focus,new Vector3(-19,12,-30),72);}}
 protected override void StopSounds(){rumble?.Stop();siren?.Stop();if(bays!=null)foreach(var b in bays)if(b!=null){b.wind?.Stop();b.strain?.Stop();}}
 protected override void StopGame(){if(bays!=null)foreach(var b in bays)if(b!=null)b.ReelClear();}
}
}
